package com.automation.sites.saucedemo.tests;

import com.automation.sites.core.KeywordScriptSuiteBase;

/**
 * Runs every test case in the recorded keyword script, one TestNG test per test case. Generated by
 * RecorderCli; a newly recorded test case is picked up automatically, with no Java to write.
 */
public class RecordedSaucedemoKeywordTest extends KeywordScriptSuiteBase {

    @Override
    protected String objectRepository() {
        return "objectrepository/saucedemo.properties";
    }

    @Override
    protected String scriptPath() {
        return "src/test/resources/testdata/keyword/saucedemo_recorded_keywords.csv";
    }
}
